import json

class JSONParser:
    def __init__(self):
        self.factory_functions = {}

    def add_factory_function(self, id, func):
        self.factory_functions[id] = func

    def from_json(self, json_str):
        data = json.loads(json_str)
        if ""type"" in data:
            id = data[""type""]
            if id in self.factory_functions:
                return self.factory_functions[id](data)
        return None

    def to_json(self, instance):
        data = {""type"": instance.__class__.__name__}
        for key, value in vars(instance).items():
            if not key.startswith(""_""):
                data[key] = value
        return json.dumps(data)
