0,"Design a Flask API to manage a book collection. Include CRUD operations (add, retrieve, update, delete) for books with attributes: title, author, publication year, and genre. Implement routes for adding books, getting all books, updating book details, and deleting by ID. Add endpoints for searching by title or author and sorting by publication year or genre. Ensure proper error handling for invalid requests or missing data.",502,,"['```
from flask import Flask, jsonify, request

app = Flask(__name__)
app.config[""JSONIFY_PRETTYPRINT_REGULAR""] = False

# Define database schema
books = []

# Create endpoint for adding a book
@app.route(""/book"", methods=[""POST""])
def add_book():
    data = request.get_json()
    book = {
        ""title"": data[""title""],
        ""author"": data[""author""],
        ""publication_year"": data[""publication_year""],
        ""genre"": data[""genre""]
    }
    books.append(book)
    return jsonify({""message"": f""Book {data['title']} by {data['author']} added successfully""}), 201

# Create endpoint for retrieving all books
@app.route(""/books"", methods=[""GET""])
def get_all_books():
    return jsonify([book for book in books]), 200

# Create endpoint for updating a book
@app.route(""/book/<int:id>"", methods=[""PUT""])
def update_book(id):
    data = request.get_json()
    book = next((book for book in books if book[""id""] == id), None)
    if not book:
        return jsonify({""message"": f""Book with ID {id} not found""}), 404
    book.update(data)
    return jsonify({""message"": f""Book {book['title']} by {book['author']} updated successfully""}), 200

# Create endpoint for deleting a book by ID
@app.route(""/book/<int:id>"", methods=[""DELETE""])
def delete_book(id):
    book = next((book for book in books if book[""id""] == id), None)
    if not book:
        return jsonify({""message"": f""Book with ID {id} not found""}), 404
    books.remove(book)
    return jsonify({""message"": f""Book {book['title']} by {book['author']} deleted successfully""}), 200

# Create endpoint for searching by title or author
@app.route(""/books/search"", methods=[""GET""])
def search_by_title_or_author():
    query = request.args.get(""query"")
    if not query:
        return jsonify({""message"": ""No query provided""}), 400
    books_found = [book for book in books if query in (book[""title""], book[""author""])]
    return jsonify([book for book in books_found]), 200

# Create endpoint for sorting by publication year or genre
@app.route(""/books/sort"", methods=[""GET""])
def sort_by_publication_year_or_genre():
    order = request.args.get(""order"")
    if not order:
        return jsonify({""message"": ""No order provided""}), 400
    books_sorted = sorted(books, key=lambda x: x[order])
    return jsonify([book for book in books_sorted]), 200

# Error handling for invalid requests or missing data
@app.errorhandler(404)
def not_found(e):
    return jsonify({""message"": ""Not found""}), 404

@app.errorhandler(400)
def bad_request(e):
    return jsonify({""message"": ""Bad request""}), 400

if __name__ == ""__main__"":
    app.run(debug=True)
```
