class Observation:
    def __init__(self, date, temperature, location):
        self.date = date
        self.temperature = temperature
        self.location = location

def calculate_average_temperature(observations, start_date, end_date):
    # Filter out observations based on their dates falling within the specified time period
    filtered_observations = [obs for obs in observations if start_date <= obs.date <= end_date]

    # Compute and return the average temperature for those observations
    if not filtered_observations:
        return None
    else:
        total_temperature = sum(obs.temperature for obs in filtered_observations)
        return total_temperature / len(filtered_observations)
