            print(""Invalid input. Please enter a valid dimension."")

def generate_matrix(rows, cols):
    matrix = []
    for i in range(rows):
        matrix.append([])
        for j in range(cols):
            matrix[i].append(random.randint(1, 100))
    return matrix

def display_matrix(matrix):
    print(""Your matrix:"")
    for row in matrix:
        print(*row)

def save_to_file(matrix):
    with open(""output.txt"", ""w"") as f:
        for row in matrix:
            for item in row:
                f.write(str(item) + ""\t"")
            f.write(""\n"")

if __name__ == ""__main__"":
    dimensions = get_dimensions()
    matrix = generate_matrix(*dimensions)
    display_matrix(matrix)
    save_to_file(matrix)
