0,"Create a Python script using standard library functions for file management. Accept command-line arguments for actions: listing directory contents with `--ls`, changing current directory with `--cd`, and creating a new directory with `--mkdir`. Display usage instructions if no arguments are provided. Exit with the correct code.",121,,"['```
import sys
import os

def main():
    # Get command-line arguments
    args = sys.argv[1:]

    # Check for valid arguments
    if len(args) == 0:
        print(""Usage: python file_management.py [--ls | --cd <directory> | --mkdir <directory>]"")
        exit(1)

    # Handle actions based on command-line arguments
    if args[0] == ""--ls"":
        list_contents()
    elif args[0] == ""--cd"":
        change_directory(args[1])
    elif args[0] == ""--mkdir"":
        create_directory(args[1])
    else:
        print(""Invalid command-line argument"")
        exit(1)

def list_contents():
    # List the contents of the current directory
    for file in os.listdir("".""):
        print(file)

def change_directory(directory):
    # Change to a new directory
    try:
        os.chdir(directory)
    except FileNotFoundError:
        print(""Directory not found"")
        exit(1)

def create_directory(directory):
    # Create a new directory
    try:
        os.mkdir(directory)
    except OSError:
        print(""Failed to create directory"")
