import json
import os
import sys
import importlib
from contextlib import contextmanager
from typing import Dict, List, Optional

class NLPProcessor:
    def __init__(self, config: Dict[str, str], cache: Dict[str, any]):
        self.config = config
        self.cache = cache

    @contextmanager
    def load_library(self, library_name: str) -> Optional[any]:
        if library_name in self.cache:
            yield self.cache[library_name]
        else:
            try:
                module = importlib.import_module(""."" + library_name, ""nlp_libraries"")
                self.cache[library_name] = module
                yield module
            except ModuleNotFoundError as e:
                print(f""Failed to load {library_name}: {e}"")
                return None

    def process_text(self, text: str) -> Dict[str, any]:
        results = {}
        for library in self.config[""libraries""]:
            with self.load_library(library) as module:
                if module is not None:
                    results[library] = module.process_text(text)

        return results

def get_available_libraries() -> List[str]:
    available_libraries = []
    for library in os.listdir(""nlp_libraries""):
        if library.endswith("".py"") and os.path.isfile(os.path.join(""nlp_libraries"", library)):
            available_libraries.append(library[:-3])
    return available_libraries

def configure_nlp_processor() -> Dict[str, any]:
    config = {
        ""libraries"": [],
    }
    with open(""config.json"") as f:
        config = json.load(f)
    cache = {}
    return NLPProcessor(config, cache)

def main():
    nlp_processor = configure_nlp_processor()
    available_libraries = get_available_libraries()
    for library in available_libraries:
        if library in config[""libraries""]:
            with nlp_processor.load_library(library) as module:
                if module is not None:
                    print(f""Loaded {library}"")
        else:
            print(f""Skipped {library} (not included in configuration)"")

if __name__ == ""__main__"":
    main()
