def process_csv(input_file_path: str, output_file_path: str, filter_condition: str, transformation_mapping_str):
    # Read CSV data dynamically using Python's csv module
    with open(input_file_path) as csv_file:
        reader = csv.DictReader(csv_file)
        filtered_rows = []

        for row in reader:
            if eval(filter_condition):
                filtered_rows.append(row)

    # Apply transformations based on provided key-value pairs
    transformation_map = {}
    transformation_dict_str = transformation_mapping_str.replace('\'', '\""')

    for pair in transformation_dict_str.split(','):
        key, value = pair.split(':')
        if key in ['hex', 'int']:
            value_function = eval(value)
            transformation_map[key] = value_function
        else:
            raise ValueError(f""Unknown transformation type for {key}: {value}"")

    for row in filtered_rows:
        for key, value_function in transformation_map.items():
            if key in row and key != 'hex':
                row[key] = value_function(row[key])
            elif key == 'hex' and 'hex' in row and 'int' not in row:
                try:
                    row['hex'] = hex(int(row['int']))
                except ValueError:
                    raise ValueError(f""Failed to convert '{row['int']}' to int before applying hex function"")

    # Write transformed data to JSON format using Python's json module
    with open(output_file_path, 'w') as json_file:
        json.dump(filtered_rows, json_file)

def main():
    import sys

    if len(sys.argv) != 6:
        print(""Usage: python script.py <input.csv> <output.json> <filter_condition> <transformation_mapping_string>"")
