0,"Design a Python program using built-in modules for file and directory operations. The script should accept command-line arguments for file management tasks: `--copy` for copying files, `--move` for moving files, and `--rm` for deleting files. Provide usage guidance when no arguments are specified. Ensure the script exits with the correct status code upon completion.",121,,"['```
import os
import sys

def main():
    # Get command-line arguments
    args = sys.argv[1:]

    if not args:
        print(""Usage: python file_manager.py --copy <source> <destination>"")
        print(""       python file_manager.py --move <source> <destination>"")
        print(""       python file_manager.py --rm <file>"")
        sys.exit(1)

    # Check if the command-line arguments are valid
    if not os.path.exists(args[0]):
        print(f""{args[0]} does not exist."")
        sys.exit(2)

    # Perform file management task based on command-line argument
    if args[1] == ""--copy"":
        copy_file(args[0], args[2])
    elif args[1] == ""--move"":
        move_file(args[0], args[2])
    elif args[1] == ""--rm"":
        remove_file(args[0])
    else:
        print(""Invalid command-line argument."")
        sys.exit(3)

def copy_file(source, destination):
    try:
        os.copy(source, destination)
    except OSError as e:
        print(f""Error copying file {source}: {e}"")

def move_file(source, destination):
    try:
        os.rename(source, destination)
    except OSError as e:
        print(f""Error moving file {source}: {e}"")

def remove_file(filename):
    try:
        os.remove(filename)
    except OSError as e:
        print(f""Error removing file {filename}: {e}"")

if __name__ == ""__main__"":
    main()
```
