0,"Create a Python script that handles file and directory operations through command-line arguments. The script should support three actions: `--copy` for file duplication, `--move` for relocating files, and `--rm` for file deletion. Offer usage instructions if no arguments are provided. Make sure the script terminates with the appropriate exit code upon execution completion.",121,,"['```python
import os
import sys

def main():
    args = sys.argv[1:]
    if len(args) == 0:
        print(""Usage: python file_operations.py --copy|--move|--rm <source> <destination>"")
        return 0

    action = args[0]
    source = args[1]
    destination = args[2]

    if action == ""--copy"":
        copy(source, destination)
    elif action == ""--move"":
        move(source, destination)
    elif action == ""--rm"":
        rm(destination)
    else:
        print(""Invalid action"")
        return 1

def copy(source, destination):
    try:
        os.copy(source, destination)
    except FileNotFoundError:
        print(f""File {source} does not exist"")
        return 1
    except Exception as e:
        print(f""Error copying file {source}: {e}"")
        return 2

def move(source, destination):
    try:
        os.rename(source, destination)
    except FileNotFoundError:
        print(f""File {source} does not exist"")
        return 1
    except Exception as e:
        print(f""Error moving file {source}: {e}"")
        return 2

def rm(destination):
    try:
        os.remove(destination)
    except FileNotFoundError:
        print(f""File {destination} does not exist"")
        return 1
    except Exception as e:
        print(f""Error deleting file {destination}: {e}"")
        return 2

if __name__ == ""__main__"":
    main()
```
This script takes command-line arguments and performs the specified action on a file or directory. The actions are: `--copy` for duplicating files, `--move` for relocating files, and `--rm` for deleting files. If no arguments are provided, the script will print usage instructions. The script terminates with an appropriate exit code upon completion.']",0,[0],[],True,0,0,0,

