def process_text(input_file_path, output_file_path, keywords, replacement_dict):
    try:
        # Read input file line by line
        with open(input_file_path, 'r') as input_file:
            lines = input_file.readlines()

        # Process each line and replace keywords with their corresponding replacements
        modified_lines = []
        for line in lines:
            modified_line = line
            for keyword, replacement in replacement_dict.items():
                if keyword in line:
                    modified_line = modified_line.replace(keyword, replacement)
            modified_lines.append(modified_line)

        # Write modified content to output file
        with open(output_file_path, 'w') as output_file:
            for line in modified_lines:
                output_file.write(line)
    except Exception as e:
        # Log any exceptions that occurred during file reading or writing operations
        print(f""Error: {e}"")
