def generate_student_schedule(course_tuples, enrollment_probability):
    # Create a dictionary to map students to their assigned courses
    student_to_courses = {}

    # Loop through each course tuple and process the students enrolled in it
    for course_tuple in course_tuples:
        course_name, max_capacity, students = course_tuple

        # Check if there are enough spots available in this course
        if len(student_to_courses) < max_capacity:
            # Loop through the list of students enrolled in this course
            for student in students:
                # Check if the student is already assigned to a different course
                if student not in student_to_courses or student_to_courses[student] == course_name:
                    # Assign the student to this course, based on the enrollment probability distribution
                    assign_course = random.choices(
                        [True, False], weights=enrollment_probability[course_tuple]
                    )
                    if assign_course:
                        student_to_courses[student] = course_name

